def majority_element(arr):
    """
    This function implements the Boyer-Moore Voting Algorithm to find the majority element in an array of integers.

    Arguments:
        arr {list} -- A list of integers

    Returns:
        int -- The majority element in the given array
    """

    # Initialize the majority counter to 0
    majority = 0

    # Iterate through the array
    for i in range(len(arr)):
        # Count the number of votes for each element
        vote_counts = {}
        for j in range(len(arr)):
            if arr[i] == arr[j]:
                vote_counts[arr[i]] += 1
            else:
                vote_counts[arr[j]] += 1

        # Initialize the majority element
        if vote_counts[arr[0]] > majority:
            majority = arr[0]

        # Iterate through the array again and update the vote counts
        for i in range(len(arr)):
            if arr[i] != majority:
                vote_counts[arr[i]] -= 1

    # Return the majority element
    return majority<s>

